<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Relatórios';$report=$_GET['report']??'vendas';$from=$_GET['de']??date('Y-m-01');$to=$_GET['ate']??today();$product=(int)($_GET['produto_id']??0);$client=(int)($_GET['cliente_id']??0);$user=(int)($_GET['usuario_id']??0);$payment=trim($_GET['pagamento']??'');$status=trim($_GET['status']??'');$origin=trim($_GET['origem']??'');$products=$pdo->query('SELECT id,nome FROM produtos ORDER BY nome')->fetchAll();$clients=$pdo->query('SELECT id,nome FROM clientes ORDER BY nome')->fetchAll();$users=$pdo->query('SELECT id,nome FROM usuarios ORDER BY nome')->fetchAll();
include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Relatórios</h1><button class="btn secondary no-print" onclick="printPage()">Imprimir</button></div><div class="tabs no-print"><a class="tab <?=$report==='vendas'?'active':''?>" href="?report=vendas">Vendas</a><a class="tab <?=$report==='estoque'?'active':''?>" href="?report=estoque">Estoque</a><a class="tab <?=$report==='encomendas'?'active':''?>" href="?report=encomendas">Encomendas</a><a class="tab <?=$report==='financeiro'?'active':''?>" href="?report=financeiro">Financeiro</a><a class="tab <?=$report==='caixa'?'active':''?>" href="?report=caixa">Caixa</a></div><div class="card no-print"><form method="get"><input type="hidden" name="report" value="<?=e($report)?>"><div class="form-grid"><div class="field col-3"><label>De</label><input type="date" name="de" value="<?=e($from)?>"></div><div class="field col-3"><label>Até</label><input type="date" name="ate" value="<?=e($to)?>"></div><?php if($report==='vendas'): ?><div class="field col-3"><label>Produto</label><select name="produto_id"><option value="0">Todos</option><?php foreach($products as $p): ?><option value="<?=$p['id']?>" <?=$product===$p['id']?'selected':''?>><?=e($p['nome'])?></option><?php endforeach;?></select></div><div class="field col-3"><label>Cliente</label><select name="cliente_id"><option value="0">Todos</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>" <?=$client===$c['id']?'selected':''?>><?=e($c['nome'])?></option><?php endforeach;?></select></div><div class="field col-3"><label>Usuário</label><select name="usuario_id"><option value="0">Todos</option><?php foreach($users as $u): ?><option value="<?=$u['id']?>" <?=$user===$u['id']?'selected':''?>><?=e($u['nome'])?></option><?php endforeach;?></select></div><div class="field col-3"><label>Pagamento</label><select name="pagamento"><option value="">Todos</option><option <?=$payment==='Dinheiro'?'selected':''?>>Dinheiro</option><option <?=$payment==='PIX'?'selected':''?>>PIX</option><option <?=$payment==='Débito'?'selected':''?>>Débito</option><option <?=$payment==='Crédito'?'selected':''?>>Crédito</option></select></div><?php elseif($report==='encomendas'): ?><div class="field col-3"><label>Cliente</label><select name="cliente_id"><option value="0">Todos</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>" <?=$client===$c['id']?'selected':''?>><?=e($c['nome'])?></option><?php endforeach;?></select></div><div class="field col-3"><label>Status</label><select name="status"><option value="">Todos</option><?php foreach(['Aberta','Aguardando','Confirmada','Em preparação','Pronta','Entregue','Cancelada'] as $x): ?><option <?=$status===$x?'selected':''?>><?=e($x)?></option><?php endforeach;?></select></div><div class="field col-3"><label>Origem</label><select name="origem"><option value="">Todas</option><option <?=$origin==='portal'?'selected':''?>>portal</option><option <?=$origin==='balcão'?'selected':''?>>balcão</option></select></div><div class="field col-3"><label>Usuário</label><select name="usuario_id"><option value="0">Todos</option><?php foreach($users as $u): ?><option value="<?=$u['id']?>" <?=$user===$u['id']?'selected':''?>><?=e($u['nome'])?></option><?php endforeach;?></select></div><?php endif; ?><div class="col-12"><button class="btn secondary">Aplicar filtros</button></div></div></form></div>
<?php if($report==='vendas'):{ $sql="SELECT DISTINCT v.*,c.nome cliente,u.nome usuario_nome FROM vendas v LEFT JOIN clientes c ON c.id=v.cliente_id JOIN usuarios u ON u.id=v.usuario_id";$joins='';$conds=['date(v.data_venda) BETWEEN ? AND ?'];$args=[$from,$to];if($product){$joins.=' JOIN venda_itens fi ON fi.venda_id=v.id';$conds[]='fi.produto_id=?';$args[]=$product;}if($client){$conds[]='v.cliente_id=?';$args[]=$client;}if($user){$conds[]='v.usuario_id=?';$args[]=$user;}if($payment){$conds[]='v.forma_pagamento=?';$args[]=$payment;}$sql.=$joins.' WHERE '.implode(' AND ',$conds).' ORDER BY v.data_venda DESC';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$subtotal=array_sum(array_column($rows,'subtotal'));$disc=array_sum(array_column($rows,'desconto'));$total=array_sum(array_column($rows,'total')); ?>
<div class="card print-header print-only"><h1><?=e(setting('nome_livraria',APP_NAME))?></h1><div><?=e(setting('endereco_livraria'))?></div></div><div class="grid grid-3"><div class="card stat"><span class="label">Quantidade</span><span class="value"><?=count($rows)?></span></div><div class="card stat"><span class="label">Subtotal</span><span class="value"><?=money($subtotal)?></span></div><div class="card stat"><span class="label">Descontos</span><span class="value"><?=money($disc)?></span></div></div><div class="card" style="margin-top:16px"><h3>Vendas</h3><div class="table-wrap"><table class="table"><thead><tr><th>Nº</th><th>Data</th><th>Cliente</th><th>Usuário</th><th>Pagamento</th><th>Subtotal</th><th>Desconto</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['numero'])?></td><td><?=datetime_br($r['data_venda'])?></td><td><?=e($r['cliente']?:'—')?></td><td><?=e($r['usuario_nome'])?></td><td><?=e($r['forma_pagamento'])?></td><td><?=money($r['subtotal'])?></td><td><?=money($r['desconto'])?></td><td><?=money($r['total'])?></td></tr><?php endforeach;?><tr><th colspan="7" class="text-right">Total</th><th><?=money($total)?></th></tr></tbody></table></div></div>
<?php } elseif($report==='estoque'):{ $rows=$pdo->query("SELECT p.*,c.nome categoria FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE p.ativo=1 ORDER BY p.nome")->fetchAll(); ?><div class="card"><h3>Estoque atual</h3><div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Produto</th><th>Categoria</th><th>Estoque</th><th>Mínimo</th><th>Custo</th><th>Preço</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['codigo'])?></td><td><?=e($r['nome'])?></td><td><?=e($r['categoria'])?></td><td><?=e($r['estoque'])?></td><td><?=e($r['estoque_minimo'])?></td><td><?=money($r['custo'])?></td><td><?=money($r['preco'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php } elseif($report==='encomendas'):{ $sql="SELECT e.*,c.nome cliente,u.nome usuario_nome FROM encomendas e JOIN clientes c ON c.id=e.cliente_id LEFT JOIN usuarios u ON u.id=e.usuario_id";$conds=['date(e.data_hora) BETWEEN ? AND ?'];$args=[$from,$to];if($client){$conds[]='e.cliente_id=?';$args[]=$client;}if($status){$conds[]='e.status=?';$args[]=$status;}if($origin){$conds[]='e.origem=?';$args[]=$origin;}if($user){$conds[]='e.usuario_id=?';$args[]=$user;}$st=$pdo->prepare($sql.' WHERE '.implode(' AND ',$conds).' ORDER BY e.data_hora DESC');$st->execute($args);$rows=$st->fetchAll(); ?><div class="card"><h3>Encomendas</h3><div class="table-wrap"><table class="table"><thead><tr><th>Nº</th><th>Data</th><th>Cliente</th><th>Status</th><th>Origem</th><th>Total</th><th>Usuário</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['numero'])?></td><td><?=datetime_br($r['data_hora'])?></td><td><?=e($r['cliente'])?></td><td><?=status_badge($r['status'])?></td><td><?=e($r['origem'])?></td><td><?=money($r['total'])?></td><td><?=e($r['usuario_nome'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php } elseif($report==='financeiro'):{ $st=$pdo->prepare('SELECT * FROM movimentacoes_financeiras WHERE date(COALESCE(data_pagamento, vencimento, criado_em)) BETWEEN ? AND ? ORDER BY id DESC');$st->execute([$from,$to]);$rows=$st->fetchAll(); ?><div class="card"><h3>Movimentações financeiras</h3><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Tipo</th><th>Categoria</th><th>Descrição</th><th>Valor</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=date_br($r['data_pagamento']?:$r['vencimento']?:$r['criado_em'])?></td><td><?=e($r['tipo'])?></td><td><?=e($r['categoria'])?></td><td><?=e($r['descricao'])?></td><td><?=money($r['valor'])?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php } else: { $st=$pdo->prepare("SELECT c.* FROM caixas c WHERE date(c.abertura_em) BETWEEN ? AND ? ORDER BY c.id DESC");$st->execute([$from,$to]);$rows=$st->fetchAll(); ?><div class="card"><h3>Caixa</h3><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Abertura</th><th>Fechamento</th><th>Inicial</th><th>Esperado</th><th>Informado</th><th>Diferença</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=$r['id']?></td><td><?=datetime_br($r['abertura_em'])?></td><td><?=datetime_br($r['fechamento_em'])?></td><td><?=money($r['valor_inicial'])?></td><td><?=money($r['valor_esperado'])?></td><td><?=money($r['valor_informado'])?></td><td><?=money($r['diferenca'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php } endif; include __DIR__.'/../../includes/footer.php'; ?>
